package android.content; import java.util.*; public class SharedPreferences { public final Map<String,Object> data=new HashMap<>(); public long getLong(String k,long d){Object v=data.get(k);return v==null?d:((Number)v).longValue();} public int getInt(String k,int d){Object v=data.get(k);return v==null?d:((Number)v).intValue();} public boolean getBoolean(String k,boolean d){Object v=data.get(k);return v==null?d:(Boolean)v;} public String getString(String k,String d){Object v=data.get(k);return v==null?d:(String)v;} public Editor edit(){return new Editor();} public class Editor {Map<String,Object> add=new HashMap<>();Set<String> remove=new HashSet<>();public Editor putLong(String k,long v){add.put(k,v);return this;}public Editor putInt(String k,int v){add.put(k,v);return this;}public Editor putBoolean(String k,boolean v){add.put(k,v);return this;}public Editor putString(String k,String v){add.put(k,v);return this;}public Editor remove(String k){remove.add(k);return this;}public boolean commit(){for(String k:remove)data.remove(k);data.putAll(add);return true;}}}